/**
 * Tangle SSO for agent apps. OIDC callers use the registered runtime client
 * with S256 PKCE. Legacy API-key callers remain explicit during migration.
 * OIDC never falls back to cross-site exchange. Account matching and native
 * session cookie minting remain shared.
 */

import type { OidcTokens, PlatformOidcClient } from '@tangle-network/agent-runtime/platform'
import { clearCookieHeader, readCookieValue, serializeCookie } from '../web/index'

const DEFAULT_STATE_TTL_SECONDS = 600
const DEFAULT_SESSION_TTL_SECONDS = 60 * 60 * 24 * 7
const DEFAULT_REDIRECT_PATH = '/app'
const DEFAULT_LOGIN_PATH = '/login'
const DEFAULT_SESSION_COOKIE = 'better-auth.session_token'

// ── Signed state ────────────────────────────────────────────────────────────

/** Define configuration options for managing SSO state including secret, lifetime, and clock injection */
export interface SsoStateConfig {
  /** HMAC-SHA256 secret (e.g. the app's auth secret). */
  secret: string
  /** State lifetime in ms. Default 600 000. */
  ttlMs?: number
  /** Injectable clock (ms since epoch). Default Date.now. */
  now?: () => number
}

function randomHex(bytes: number): string {
  const buf = new Uint8Array(bytes)
  crypto.getRandomValues(buf)
  return Array.from(buf, (b) => b.toString(16).padStart(2, '0')).join('')
}

async function hmacBytes(secret: string, value: string): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  )
  return new Uint8Array(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(value)))
}

async function hmacHex(secret: string, value: string): Promise<string> {
  return Array.from(await hmacBytes(secret, value), (b) => b.toString(16).padStart(2, '0')).join('')
}

function constantTimeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return diff === 0
}

/** Mint a `<randomHex32>.<timestamp36>.<hmacHex>` state value. The timestamp
 *  is inside the signed payload, so expiry survives cookie-attribute tampering. */
export async function createSignedSsoState(config: SsoStateConfig): Promise<string> {
  if (!config.secret) throw new Error('SsoStateConfig.secret is required')
  const now = config.now ?? Date.now
  const payload = `${randomHex(16)}.${now().toString(36)}`
  return `${payload}.${await hmacHex(config.secret, payload)}`
}

/** Verify the MAC (constant-time) and the signed TTL. */
export async function verifySignedSsoState(state: string, config: SsoStateConfig): Promise<boolean> {
  if (!config.secret) throw new Error('SsoStateConfig.secret is required')
  const parts = state.split('.')
  if (parts.length !== 3) return false
  const [random, timestamp, mac] = parts
  if (!random || !timestamp || !mac || !/^[0-9a-z]+$/.test(timestamp)) return false
  const expected = await hmacHex(config.secret, `${random}.${timestamp}`)
  if (!constantTimeEqual(mac, expected)) return false
  const mintedAt = parseInt(timestamp, 36)
  if (!Number.isFinite(mintedAt)) return false
  const now = config.now ?? Date.now
  const ttlMs = config.ttlMs ?? DEFAULT_STATE_TTL_SECONDS * 1000
  const age = now() - mintedAt
  return age >= 0 && age <= ttlMs
}

// ── Seams ───────────────────────────────────────────────────────────────────

/** Describe the result of exchanging SSO credentials including API key, user info, and optional plan details */
export interface TangleSsoExchangeResult {
  apiKey: string
  /** The platform's canonical verified-email proof. */
  emailVerified: boolean
  user: { id: string; email: string; name?: string | null }
  plan?: { tier: string } | null
}

/** Structural mirror of the platform auth wire client — any object with these
 *  two methods satisfies it without this module importing the concrete class. */
export interface TangleSsoAuthClient {
  authorizeUrl(options: { state: string; redirectUri?: string }): string
  exchange(code: string): Promise<TangleSsoExchangeResult>
}

/** The runtime owns the OIDC wire protocol and its types. */
export type TangleOidcSsoAuthClient = Pick<
  PlatformOidcClient,
  'authorizeUrl' | 'exchange' | 'refresh' | 'userinfo' | 'revoke'
>

/** Local account shape required by the verified Tangle SSO account policy.
 * Consumers map their user/link tables into this shape before resolving an
 * exchange. */
export interface TangleSsoLocalAccount {
  userId: string
  email: string
  emailVerified: boolean
  platformUserId: string | null
}

/** Reasons a local account lookup must stop instead of linking an exchange. */
export type TangleSsoAccountConflictReason =
  | 'ambiguous-platform-id'
  | 'platform-id-email-conflict'
  | 'unverified-email'
  | 'email-platform-id-conflict'
  | 'ambiguous-email'
  | 'invalid-platform-id'
  | 'invalid-email'
  | 'platform-match-mismatch'
  | 'email-match-mismatch'

/** Result of applying the verified Tangle SSO account matching policy. */
export type TangleSsoAccountResolution =
  | { kind: 'existing'; userId: string; matchedBy: 'platform-id' | 'verified-email' }
  | { kind: 'create' }
  | { kind: 'reject'; reason: TangleSsoAccountConflictReason }

/** Inputs for {@link resolveTangleSsoAccount}. `platformUserId` is the
 * platform's stable identity. */
export interface TangleSsoAccountResolutionInput {
  email: string
  platformMatches: readonly TangleSsoLocalAccount[]
  emailMatches: readonly TangleSsoLocalAccount[]
  platformUserId: string
}

/** Normalize an email for comparisons and persistence queries. */
export function normalizeTangleSsoEmail(email: string): string {
  return email.trim().toLowerCase()
}

function normalizedPlatformUserId(value: string | null | undefined): string | null {
  const normalized = value?.trim()
  return normalized ? normalized : null
}

/**
 * Resolve a platform exchange against all local rows found by stable platform
 * identity and normalized email.
 *
 * A stable platform id takes precedence over email. Every ambiguous or
 * contradictory result rejects, and email fallback requires a verified local
 * email that is not already bound to another platform id. The resolver is
 * pure so each consumer can query its own schema, including schemas without
 * unique indexes, then rerun it after an insert race.
 */
export function resolveTangleSsoAccount(
  input: TangleSsoAccountResolutionInput,
): TangleSsoAccountResolution {
  const email = normalizeTangleSsoEmail(input.email)
  const platformUserId = normalizedPlatformUserId(input.platformUserId)
  if (!email) return { kind: 'reject', reason: 'invalid-email' }
  if (!platformUserId) return { kind: 'reject', reason: 'invalid-platform-id' }

  if (input.platformMatches.length > 1) {
    return { kind: 'reject', reason: 'ambiguous-platform-id' }
  }
  if (input.emailMatches.length > 1) {
    return { kind: 'reject', reason: 'ambiguous-email' }
  }

  if (input.platformMatches.some((account) => normalizedPlatformUserId(account.platformUserId) !== platformUserId)) {
    return { kind: 'reject', reason: 'platform-match-mismatch' }
  }
  if (input.emailMatches.some((account) => normalizeTangleSsoEmail(account.email) !== email)) {
    return { kind: 'reject', reason: 'email-match-mismatch' }
  }

  const platformMatch = input.platformMatches[0]
  const emailMatch = input.emailMatches[0]

  if (platformMatch) {
    if (emailMatch && emailMatch.userId !== platformMatch.userId) {
      return { kind: 'reject', reason: 'platform-id-email-conflict' }
    }
    return { kind: 'existing', userId: platformMatch.userId, matchedBy: 'platform-id' }
  }

  if (!emailMatch) return { kind: 'create' }
  const existingPlatformUserId = normalizedPlatformUserId(emailMatch.platformUserId)
  if (existingPlatformUserId === platformUserId) {
    return { kind: 'existing', userId: emailMatch.userId, matchedBy: 'platform-id' }
  }
  if (emailMatch.emailVerified !== true) {
    return { kind: 'reject', reason: 'unverified-email' }
  }

  if (existingPlatformUserId && existingPlatformUserId !== platformUserId) {
    return { kind: 'reject', reason: 'email-platform-id-conflict' }
  }

  // The platform proof is already verified. A verified local email row is safe
  // to link when it is unbound or already carries this same platform id.
  return { kind: 'existing', userId: emailMatch.userId, matchedBy: 'verified-email' }
}

/** Thrown by an account store when the verified SSO policy rejects a link. */
export class TangleSsoAccountConflictError extends Error {
  readonly reason: TangleSsoAccountConflictReason

  constructor(reason: TangleSsoAccountConflictReason, message = 'Tangle SSO account linking was rejected') {
    super(message)
    this.name = 'TangleSsoAccountConflictError'
    this.reason = reason
  }
}

/** Thrown by `upsertUserByEmail` when the app-local user row cannot be
 *  created; the callback handler maps it to `?error=tangle_user_create_failed`.
 *  Any other store error propagates. */
export class TangleSsoUserCreateError extends Error {
  constructor(message = 'Failed to create local user for Tangle SSO') {
    super(message)
    this.name = 'TangleSsoUserCreateError'
  }
}

/**
 * Account persistence seam. Covers both storage styles in use: link-table
 * apps (a per-user platform-link row) and session-column apps (the key on the
 * session row) — `saveTangleLink` receives both `userId` and `sessionToken`,
 * and each app persists with the key it needs. `createSession` runs first so
 * the token is always available to `saveTangleLink`.
 */
export interface TangleSsoAccountStore {
  /** Resolve the local account before any user, session, or link write.
   * Implementations must query every candidate by stable platform id and
   * normalized email, then apply `resolveTangleSsoAccount` (or an equivalent
   * fail-closed policy). The callback rejects `kind: 'reject'` results before
   * it calls `upsertUserByEmail`. */
  resolveAccount(input: { email: string; platformUserId: string }): Promise<TangleSsoAccountResolution>
  /** Find-or-create the app-local user selected by `resolveAccount`.
   * `tangleUserId` is the platform's stable user id — match on it first when
   * the app stores it (emails are mutable on the platform; the id is not),
   * falling back to email for first-time logins. */
  upsertUserByEmail(input: {
    email: string
    name: string | null
    tangleUserId: string
    resolution: Exclude<TangleSsoAccountResolution, { kind: 'reject' }>
  }): Promise<{ userId: string }>
  /** Create an app session row; returns the session-cookie token value. */
  createSession(input: {
    userId: string
    expiresAt: Date
    ipAddress: string | null
    userAgent: string | null
  }): Promise<{ token: string }>
  /** Persist the platform link (API key + platform identity). */
  saveTangleLink(input: {
    userId: string
    sessionToken: string
    tangleUserId: string
    email: string
    name: string | null
    apiKey: string
    planTier: string | null
  }): Promise<void>
}

/**
 * OIDC tokens are server-side credentials, not API keys. Implementations must
 * encrypt them at rest and bind them to the exact local session. Refresh and
 * disconnect must serialize updates to the same grant.
 */
export interface TangleOidcSsoAccountStore extends Omit<TangleSsoAccountStore, 'saveTangleLink'> {
  saveTangleLink(input: {
    userId: string
    sessionToken: string
    tangleUserId: string
    email: string
    name: string | null
    tokens: OidcTokens
    accessTokenExpiresAt: Date
  }): Promise<void>
  /** Remove an unpublished local session if callback persistence fails. */
  deleteSession(input: { sessionToken: string }): Promise<void>
}

// ── Session cookie ──────────────────────────────────────────────────────────

/** Successful-login context handed to the `setSessionCookie` seam. */
export interface TangleSsoSessionCookieArgs {
  /** Session token returned by `store.createSession`. */
  token: string
  /** Session expiry (now + `sessionTtlSeconds`). */
  expiresAt: Date
  /** Mirrors `sessionTtlSeconds` after defaulting. */
  ttlSeconds: number
  /** Mirrors `TangleSsoHandlerOptions.secureCookies`. */
  secure: boolean
}

/**
 * Sign a session token to better-call's signed-cookie contract — the value
 * better-auth's `getSignedCookie` verifies: `<token>.<signature>` where the
 * signature is the raw HMAC-SHA256 of the token under `secret`, encoded as
 * STANDARD base64 WITH padding (32 bytes → 44 chars ending `=`; better-call
 * rejects any other length or suffix, so url-safe/unpadded variants read back
 * as a null session). The joined value is percent-encoded once at cookie
 * serialization, matching better-call's `serializeSignedCookie` byte-exactly.
 */
export async function signSessionCookieValue(token: string, secret: string): Promise<string> {
  if (!secret) throw new Error('signSessionCookieValue requires a non-empty secret')
  const sig = await hmacBytes(secret, token)
  let bin = ''
  for (const byte of sig) bin += String.fromCharCode(byte)
  return `${token}.${btoa(bin)}`
}

/** Structural slice of a `betterAuth()` instance — only what cookie minting
 *  reads. No better-auth import: the signing contract is implemented by
 *  `signSessionCookieValue`, byte-compatible with better-auth's own
 *  `makeSignature`. */
export interface BetterAuthSessionCookieSource {
  $context: PromiseLike<{
    secret: string
    authCookies: {
      sessionToken: {
        /** Final cookie name — better-auth decides the `__Secure-` prefix
         *  (and any `advanced.cookiePrefix`) once at `betterAuth()` init. */
        name: string
        attributes: {
          secure?: boolean
          sameSite?: string
          path?: string
          httpOnly?: boolean
          domain?: string
        }
      }
    }
  }>
}

/** Define options to customize warning behavior for shadowed cookie names in authentication sessions */
export interface BetterAuthSessionCookieMinterOptions {
  /** Receives the shadowed-cookie-name warning (see below). Default
   *  console.warn. */
  warn?: (message: string) => void
}

/**
 * Canonical `setSessionCookie` wiring for better-auth apps: mint the session
 * Set-Cookie exactly as better-auth's own login flows do — name + attributes
 * from `auth.$context.authCookies.sessionToken` (better-auth stays
 * authoritative over prefix/name/attributes) and the value signed to
 * better-call's `getSignedCookie` contract. A raw unprefixed
 * `better-auth.session_token` left by an earlier login is explicitly expired
 * so it cannot shadow the real cookie.
 *
 * Warns when the app's session cookie still has better-auth's DEFAULT name:
 * the Tangle platform (id.tangle.tools) sets a `Domain=.tangle.tools` cookie
 * under that exact name, and equal-path cookies are sent oldest-first — the
 * platform's cookie is always older (the user signs in there before the app's
 * callback runs), so the app reads the platform's token, fails its own
 * signature check, and every fresh login lands logged-out. Per-app
 * `advanced.cookiePrefix` is the fix.
 *
 * Throws on a domain-scoped session cookie for the same reason: a
 * `Domain=`-wide session cookie is exactly the shadowing footgun.
 */
export function createBetterAuthSessionCookieMinter(
  auth: BetterAuthSessionCookieSource,
  options: BetterAuthSessionCookieMinterOptions = {},
): (args: TangleSsoSessionCookieArgs) => Promise<string[]> {
  const warn = options.warn ?? ((message: string) => console.warn(message))
  return async ({ token, ttlSeconds }) => {
    const ctx = await auth.$context
    if (!ctx.secret) {
      throw new Error('createBetterAuthSessionCookieMinter: auth context has no secret')
    }
    const { name, attributes } = ctx.authCookies.sessionToken
    if (attributes.domain) {
      throw new Error(
        `createBetterAuthSessionCookieMinter: refusing a domain-scoped session cookie (Domain=${attributes.domain}) — ` +
          'a domain-wide session cookie shadows sibling apps that share the parent domain',
      )
    }
    if (name === DEFAULT_SESSION_COOKIE || name === `__Secure-${DEFAULT_SESSION_COOKIE}`) {
      warn(
        `[tangle-sso] session cookie is named "${name}" — better-auth's default. ` +
          'The Tangle platform (id.tangle.tools) sets a Domain=.tangle.tools cookie under the same name, ' +
          "and the platform's (older) cookie wins the Cookie-header order, so this app's sessions read back null. " +
          "Set a per-app prefix: betterAuth({ advanced: { cookiePrefix: '<app>' } }).",
      )
    }
    const sameSite = typeof attributes.sameSite === 'string' ? attributes.sameSite : 'lax'
    const cookieOptions = {
      name,
      path: typeof attributes.path === 'string' ? attributes.path : '/',
      httpOnly: attributes.httpOnly !== false,
      sameSite: (sameSite.charAt(0).toUpperCase() + sameSite.slice(1)) as 'Lax' | 'Strict' | 'None',
      secure: Boolean(attributes.secure) || name.startsWith('__Secure-'),
      maxAgeSeconds: ttlSeconds,
    }
    const cookies = [serializeCookie(await signSessionCookieValue(token, ctx.secret), cookieOptions)]
    if (name !== DEFAULT_SESSION_COOKIE) {
      cookies.push(clearCookieHeader({ ...cookieOptions, name: DEFAULT_SESSION_COOKIE }))
    }
    return cookies
  }
}

// ── Handlers ────────────────────────────────────────────────────────────────

/** Define configuration options for handling Tangle SSO authentication and session management */
export interface TangleSsoHandlerOptions {
  protocol?: 'legacy'
  auth: TangleSsoAuthClient
  store: TangleSsoAccountStore
  /** HMAC secret for the state cookie. */
  stateSecret: string
  /** Absolute callback URL registered with the platform. */
  callbackUrl: string
  stateCookieName: string
  /** Default 'better-auth.session_token'. Ignored when `setSessionCookie` is
   *  provided. The default path prepends `__Secure-` iff `secureCookies`. */
  sessionCookieName?: string
  /** Mint the host auth framework's own session cookie(s); return complete
   *  Set-Cookie header values (the handler appends them verbatim and sets no
   *  session cookie itself). Supply this when the framework should stay
   *  authoritative over name/prefix/signing/attributes — e.g. better-auth:
   *  `auth.$context.authCookies.sessionToken` + `makeSignature`. */
  setSessionCookie?: (
    args: TangleSsoSessionCookieArgs,
  ) => readonly string[] | Promise<readonly string[]>
  /** HMAC-SHA256 secret the host auth framework verifies session cookies with
   *  (better-auth: its `secret`). Required when `setSessionCookie` is absent —
   *  the default cookie is minted to better-call's signed contract via
   *  `signSessionCookieValue`; an unsigned or mis-signed value reads back as a
   *  null session, so there is deliberately no fallback to `stateSecret`
   *  (which is not guaranteed to be the auth secret). */
  sessionCookieSecret?: string
  /** Adds `Secure` to every cookie this module sets, and (default session
   *  cookie only) the `__Secure-` name prefix. Must match the auth
   *  framework's own secure-cookie decision (better-auth: https `baseURL` /
   *  `advanced.useSecureCookies`), or it will look up a different cookie name
   *  than the one set here. */
  secureCookies: boolean
  /** Default 604 800 (7 days). */
  sessionTtlSeconds?: number
  /** Default 600. Applies to both the cookie Max-Age and the signed TTL. */
  stateTtlSeconds?: number
  /** Default '/app'. */
  defaultRedirectPath?: string
  /** Default '/login'. */
  loginPath?: string
  /** Failure log hook (e.g. console.error). Default no-op. */
  log?: (message: string, error?: unknown) => void
  now?: () => number
}

/** Registered OIDC client with a separate token persistence contract. */
export interface TangleOidcSsoHandlerOptions extends Omit<TangleSsoHandlerOptions, 'protocol' | 'auth' | 'store'> {
  protocol: 'oidc'
  auth: TangleOidcSsoAuthClient
  store: TangleOidcSsoAccountStore
}

/** Define handlers for SSO start and callback routes managing authentication flow and session cookies */
export interface TangleSsoHandlers {
  /** GET start route: mint + sign state, set the state cookie, 302 to the
   *  platform authorize URL. `?redirect=` carries the post-login path. */
  start(request: Request): Promise<Response>
  /** GET callback route: verify state, exchange the code, upsert the user,
   *  create the session, save the platform link, set the session cookie
   *  (via the `setSessionCookie` seam, else signed to better-call's contract
   *  with `sessionCookieSecret`), 302 to the saved redirect. Every failure
   *  302s to `loginPath?error=…` with the state cookie cleared. */
  callback(request: Request): Promise<Response>
}

/** Redirect targets must stay on this app's origin. A prefix check on `/`
 *  and `//` is not enough: in the WHATWG parser a backslash is a path
 *  separator for special schemes, so `/\host` resolves to `https://host/`,
 *  and tab or newline are stripped before parsing, so `/\t/host` is `//host`.
 *  Parse the value against a fixed origin and accept it only when that origin
 *  survives; the result is the parser's normalised path, query and fragment.
 *  Backslash and control characters are rejected up front as well, so the
 *  decision does not rest on one parser's handling of them.
 *
 *  The input staying on-origin is not enough either: dot-segment removal
 *  turns `/.//host` or `/a/..//host` into the pathname `//host` with the
 *  origin intact, and a browser resolves that Location off-origin. So the
 *  emitted value must itself resolve on-origin and come back unchanged. */
const REDIRECT_REFERENCE_ORIGIN = 'https://redirect-reference.invalid'

function sanitizeRedirectPath(value: string | null, fallback: string): string {
  if (!value || !value.startsWith('/') || /[\\\u0000-\u001f\u007f]/.test(value)) return fallback
  const path = resolveOnReferenceOrigin(value)
  if (path === null || resolveOnReferenceOrigin(path) !== path) return fallback
  return path
}

/** `path + search + hash` of `value` resolved against the reference origin,
 *  or null when the parse fails or lands on another origin. */
function resolveOnReferenceOrigin(value: string): string | null {
  let url: URL
  try {
    url = new URL(value, REDIRECT_REFERENCE_ORIGIN)
  } catch {
    return null
  }
  if (url.origin !== REDIRECT_REFERENCE_ORIGIN) return null
  return `${url.pathname}${url.search}${url.hash}`
}

function redirectResponse(location: string, headers = new Headers()): Response {
  headers.set('Location', location)
  headers.set('Cache-Control', 'no-store')
  headers.set('Referrer-Policy', 'no-referrer')
  return new Response(null, { status: 302, headers })
}

/** Real client IP: `CF-Connecting-IP` behind Cloudflare, else the first
 *  `x-forwarded-for` hop (the rest of the list is sender-controlled). */
function clientIp(request: Request): string | null {
  return (
    request.headers.get('CF-Connecting-IP') ??
    request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ??
    null
  )
}

interface StateCookiePayload {
  s: string
  r: string
  v?: string
  m?: string
}

function parseStateCookiePayload(raw: string | null): StateCookiePayload | null {
  if (!raw || raw.length > 4096) return null
  try {
    const parsed = JSON.parse(raw) as unknown
    if (parsed === null || typeof parsed !== 'object') return null
    const { s, r, v, m } = parsed as Record<string, unknown>
    if (typeof s !== 'string' || typeof r !== 'string') return null
    return { s, r, ...(typeof v === 'string' ? { v } : {}), ...(typeof m === 'string' ? { m } : {}) }
  } catch { return null }
}

function stateBinding(payload: StateCookiePayload, callbackUrl: string): string {
  return JSON.stringify([payload.s, payload.r, payload.v ?? null, callbackUrl])
}

/** Create Tangle SSO handlers to manage authentication state, callbacks, and session cookies */
export function createTangleSsoHandlers(
  opts: TangleSsoHandlerOptions | TangleOidcSsoHandlerOptions,
): TangleSsoHandlers {
  if (!opts.stateSecret) throw new Error('TangleSsoHandlerOptions.stateSecret is required')
  if (!opts.callbackUrl) throw new Error('TangleSsoHandlerOptions.callbackUrl is required')
  if (!opts.stateCookieName) throw new Error('TangleSsoHandlerOptions.stateCookieName is required')
  const callbackUrl = new URL(opts.callbackUrl)
  if (opts.protocol === 'oidc') {
    if (opts.stateSecret.length < 32) throw new Error('OIDC stateSecret must contain at least 32 characters')
    if (callbackUrl.username || callbackUrl.password || callbackUrl.hash || callbackUrl.search) {
      throw new Error('OIDC callbackUrl must be fixed and have no credentials, query, or fragment')
    }
    const loopback = ['localhost', '127.0.0.1', '[::1]'].includes(callbackUrl.hostname)
    if (callbackUrl.protocol !== 'https:' && !(callbackUrl.protocol === 'http:' && loopback)) {
      throw new Error('OIDC requires HTTPS except on loopback')
    }
    if (callbackUrl.protocol === 'https:' && !opts.secureCookies) {
      throw new Error('OIDC HTTPS callbacks require Secure cookies')
    }
  }
  const sessionCookieName = opts.sessionCookieName ?? DEFAULT_SESSION_COOKIE
  let mintSessionCookies: (args: TangleSsoSessionCookieArgs) => Promise<readonly string[]>
  if (opts.setSessionCookie) {
    const seam = opts.setSessionCookie
    mintSessionCookies = async (args) => await seam(args)
  } else if (opts.sessionCookieSecret) {
    const secret = opts.sessionCookieSecret
    mintSessionCookies = async ({ token, secure, ttlSeconds }) => [
      serializeCookie(await signSessionCookieValue(token, secret), {
        name: secure ? `__Secure-${sessionCookieName}` : sessionCookieName,
        secure,
        maxAgeSeconds: ttlSeconds,
      }),
    ]
  } else {
    throw new Error('TangleSsoHandlerOptions requires setSessionCookie or sessionCookieSecret')
  }
  const sessionTtlSeconds = opts.sessionTtlSeconds ?? DEFAULT_SESSION_TTL_SECONDS
  const stateTtlSeconds = opts.stateTtlSeconds ?? DEFAULT_STATE_TTL_SECONDS
  if (!Number.isFinite(stateTtlSeconds) || stateTtlSeconds <= 0
    || !Number.isFinite(sessionTtlSeconds) || sessionTtlSeconds <= 0) {
    throw new Error('SSO lifetimes must be positive and finite')
  }
  const defaultRedirectPath = sanitizeRedirectPath(opts.defaultRedirectPath ?? DEFAULT_REDIRECT_PATH, DEFAULT_REDIRECT_PATH)
  const loginPath = sanitizeRedirectPath(opts.loginPath ?? DEFAULT_LOGIN_PATH, DEFAULT_LOGIN_PATH)
  const log = opts.log ?? (() => {})
  const now = opts.now ?? Date.now
  const stateConfig: SsoStateConfig = { secret: opts.stateSecret, ttlMs: stateTtlSeconds * 1000, now }
  const stateCookieOpts = { name: opts.stateCookieName, secure: opts.secureCookies }
  function loginErrorRedirect(code: string): Response {
    const headers = new Headers()
    headers.append('Set-Cookie', clearCookieHeader(stateCookieOpts))
    const target = new URL(loginPath, REDIRECT_REFERENCE_ORIGIN)
    target.searchParams.set('error', code)
    return redirectResponse(`${target.pathname}${target.search}${target.hash}`, headers)
  }
  return {
    async start(request) {
      if (request.method !== 'GET') return new Response(null, { status: 405, headers: { Allow: 'GET' } })
      const url = new URL(request.url)
      if (opts.protocol === 'oidc' && url.origin !== callbackUrl.origin) {
        return loginErrorRedirect('tangle_origin_mismatch')
      }
      const redirectPath = sanitizeRedirectPath(url.searchParams.get('redirect'), defaultRedirectPath)
      const state = await createSignedSsoState(stateConfig)
      const payload: StateCookiePayload = { s: state, r: redirectPath }
      let authorizationUrl: string
      if (opts.protocol === 'oidc') {
        const { createPkcePair } = await import('@tangle-network/agent-runtime/platform')
        const pkce = await createPkcePair()
        payload.v = pkce.verifier
        payload.m = await hmacHex(opts.stateSecret, stateBinding(payload, opts.callbackUrl))
        authorizationUrl = opts.auth.authorizeUrl({ state, codeChallenge: pkce.challenge })
        if (new URL(authorizationUrl).searchParams.get('redirect_uri') !== opts.callbackUrl) {
          throw new Error('PlatformOidcClient.redirectUri must equal callbackUrl')
        }
      } else {
        authorizationUrl = opts.auth.authorizeUrl({ state, redirectUri: opts.callbackUrl })
      }
      const cookie = serializeCookie(JSON.stringify(payload), {
        ...stateCookieOpts,
        maxAgeSeconds: stateTtlSeconds,
      })
      const headers = new Headers()
      headers.append('Set-Cookie', cookie)
      return redirectResponse(authorizationUrl, headers)
    },
    async callback(request) {
      if (request.method !== 'GET') return new Response(null, { status: 405, headers: { Allow: 'GET' } })
      const url = new URL(request.url)
      if (opts.protocol === 'oidc'
        && (url.origin !== callbackUrl.origin || url.pathname !== callbackUrl.pathname)) {
        return loginErrorRedirect('tangle_origin_mismatch')
      }
      const code = url.searchParams.get('code')
      const stateFromPlatform = url.searchParams.get('state')
      if (!code || !stateFromPlatform || url.searchParams.has('error')) return loginErrorRedirect('tangle_callback_missing')
      const payload = parseStateCookiePayload(readCookieValue(request.headers.get('cookie'), opts.stateCookieName))
      if (!payload || !constantTimeEqual(payload.s, stateFromPlatform)) return loginErrorRedirect('tangle_state_mismatch')
      if (!(await verifySignedSsoState(payload.s, stateConfig))) return loginErrorRedirect('tangle_state_mismatch')
      if (opts.protocol === 'oidc' && (!payload.v || !/^[A-Za-z0-9_-]{43,128}$/.test(payload.v)
        || !payload.m || !constantTimeEqual(payload.m, await hmacHex(opts.stateSecret, stateBinding(payload, opts.callbackUrl))))) {
        return loginErrorRedirect('tangle_state_mismatch')
      }
      const tokenRequestedAt = now()
      let oidcTokens: OidcTokens | undefined
      let legacyExchange: TangleSsoExchangeResult | undefined
      let createdSession: string | undefined
      let committed = false
      try {
        let exchanged: { user: TangleSsoExchangeResult['user']; emailVerified: boolean }
        try {
          if (opts.protocol === 'oidc') {
            const result = await opts.auth.exchange(code, payload.v!)
            oidcTokens = result.tokens
            if (!oidcTokens.refreshToken || !Number.isFinite(oidcTokens.expiresIn) || oidcTokens.expiresIn! <= 0) {
              throw new Error('OIDC requires offline_access and a finite access-token lifetime')
            }
            exchanged = { user: result.user, emailVerified: result.user.emailVerified }
          } else {
            legacyExchange = await opts.auth.exchange(code)
            exchanged = legacyExchange
          }
        } catch {
          log('[tangle-sso] exchange failed')
          return loginErrorRedirect('tangle_exchange_failed')
        }
        if (exchanged.emailVerified !== true) {
          log('[tangle-sso] exchange did not include a verified-email proof')
          return loginErrorRedirect('tangle_exchange_failed')
        }
        let userId: string
        try {
          const email = normalizeTangleSsoEmail(exchanged.user.email)
          const resolution = await opts.store.resolveAccount({ email, platformUserId: exchanged.user.id })
          if (resolution.kind === 'reject') throw new TangleSsoAccountConflictError(resolution.reason)
          ;({ userId } = await opts.store.upsertUserByEmail({
            email,
            name: exchanged.user.name ?? null,
            tangleUserId: exchanged.user.id,
            resolution,
          }))
        } catch (err) {
          if (err instanceof TangleSsoAccountConflictError) {
            log('[tangle-sso] account linking conflict', err.reason)
            return loginErrorRedirect('tangle_account_conflict')
          }
          if (err instanceof TangleSsoUserCreateError) return loginErrorRedirect('tangle_user_create_failed')
          throw err
        }
        const expiresAt = new Date(now() + sessionTtlSeconds * 1000)
        const { token } = await opts.store.createSession({
          userId,
          expiresAt,
          ipAddress: clientIp(request),
          userAgent: request.headers.get('user-agent'),
        })
        createdSession = token
        const link = {
          userId,
          sessionToken: token,
          tangleUserId: exchanged.user.id,
          email: normalizeTangleSsoEmail(exchanged.user.email),
          name: exchanged.user.name ?? null,
        }
        if (opts.protocol === 'oidc') {
          await opts.store.saveTangleLink({
            ...link,
            tokens: oidcTokens!,
            accessTokenExpiresAt: new Date(tokenRequestedAt + oidcTokens!.expiresIn! * 1000),
          })
        } else {
          await opts.store.saveTangleLink({ ...link, apiKey: legacyExchange!.apiKey, planTier: legacyExchange!.plan?.tier ?? null })
        }
        const headers = new Headers()
        headers.append('Set-Cookie', clearCookieHeader(stateCookieOpts))
        const sessionCookies = await mintSessionCookies({ token, expiresAt, ttlSeconds: sessionTtlSeconds, secure: opts.secureCookies })
        for (const cookie of sessionCookies) headers.append('Set-Cookie', cookie)
        committed = true
        return redirectResponse(sanitizeRedirectPath(payload.r, defaultRedirectPath), headers)
      } catch (error) {
        if (opts.protocol !== 'oidc') throw error
        log('[tangle-sso] local session persistence failed')
        return loginErrorRedirect('tangle_session_failed')
      } finally {
        if (opts.protocol === 'oidc' && !committed) {
          if (createdSession) {
            try { await opts.store.deleteSession({ sessionToken: createdSession }) }
            catch { log('[tangle-sso] unpublished session cleanup failed') }
          }
          if (oidcTokens) {
            try { if (oidcTokens.refreshToken) await opts.auth.revoke(oidcTokens.refreshToken, 'refresh_token') }
            catch { log('[tangle-sso] rejected grant refresh revocation failed') }
            try { await opts.auth.revoke(oidcTokens.accessToken, 'access_token') }
            catch { log('[tangle-sso] rejected grant access revocation failed') }
          }
        }
      }
    },
  }
}
